  if (ax <= E + R) return herm((ax - E) / R, pE, gE * R, CONFIG.roadY, 0);
  return CONFIG.roadY;
}
/* Cao độ tim cáp chủ: parabol y = y_top − 4f·u(1 − u) */
export function tpCableY(x: number) {
  const ax = Math.abs(x);
  if (ax <= TP.towerX) { const u = (x + TP.towerX) / TP.mainSpan; return TP.saddleY - 4 * TP.sag * u * (1 - u); }
  const t = clamp((ax - TP.towerX) / (TP.cableAnchorX - TP.towerX), 0, 1);
  return lerp(TP.saddleY, TP.anchorCableY, t) - 4 * TP.sideSag * t * (1 - t);
  bridge.group.add(new THREE.Mesh(mergeGeometries(ledAll), M.led));
  bridge.details.add(new THREE.Mesh(mergeGeometries(signAll), signMat));
  hrBuildSurface(bridge);
  hrBuildDecor(bridge);
}

/* Mặt đường nối (Đống Đa phía Tây, Vân Đồn phía Đông), dải giữa, vỉa hè, đèn đường */
function hrBuildSurface(bridge: HanTunnel) {
  const Wd = HR.shoulder * 2 + HR.laneWidth * HR.lanesPerDir, c = HR.rampHalf;
